function endpointPos(id){const j=state.junctions.find(x=>x.id===id);if(j)return {x:j.x,y:j.y};for(const p of state.parts){const dx=p.a===id?-44:p.b===id?44:null;if(dx===null)continue;const r=(p.rotation||0)*Math.PI/180;return {x:p.x+dx*Math.cos(r),y:p.y+dx*Math.sin(r)}}return null}
