function runACAnalysis(){
  const f=Number($('#acFrequency').value);if(!(f>0)){toast('频率必须大于 0 Hz');return}const w=2*Math.PI*f;let ps=state.parts.map(p=>({...p}));
  ps=ps.filter(p=>!(p.type==='S'&&p.state==='open'));let parent={};for(const p of ps)for(const n of[p.a,p.b])parent[n]=n;for(const q of state.wires.filter(w=>w.a&&w.b))for(const n of[q.a,q.b])parent[n]=n;for(const q of state.junctions)parent[q.id]=q.id;const find=n=>{if(parent[n]!==n)parent[n]=find(parent[n]);return parent[n]},union=(a,b)=>{a=find(a);b=find(b);if(a!==b){if(a==='0'||b==='0')parent[a==='0'?b:a]='0';else parent[b]=a}};state.wires.filter(q=>q.a&&q.b).forEach(q=>union(q.a,q.b));ps.filter(p=>p.type==='S').forEach(p=>union(p.a,p.b));const roots=[...new Set(ps.flatMap(p=>[find(p.a),find(p.b)]))].filter(n=>n!=='0').sort((a,b)=>a.localeCompare(b,undefined,{numeric:true})),nm=new Map(roots.map((n,i)=>[n,state.custom?`N${i+1}`:n]));ps=ps.map(p=>({...p,a:find(p.a)==='0'?'0':nm.get(find(p.a)),b:find(p.b)==='0'?'0':nm.get(find(p.b))}));const nodes=state.custom?roots.map((_,i)=>`N${i+1}`):roots,g=new Map(nodes.map((n,i)=>[n,i])),vs=ps.filter(p=>p.type==='V'),N=nodes.length+vs.length;if(!N){toast('请先添加电路元件');return}
  const A=Array.from({length:N},()=>Array.from({length:N},()=>cx())),z=Array.from({length:N},()=>cx()),terms=[];const stamp=(a,b,y)=>{const i=g.get(a),j=g.get(b);if(i!==undefined)A[i][i]=cadd(A[i][i],y);if(j!==undefined)A[j][j]=cadd(A[j][j],y);if(i!==undefined&&j!==undefined){A[i][j]=csub(A[i][j],y);A[j][i]=csub(A[j][i],y)}};
  ps.forEach(p=>{const v=parseValue(p.value);if(['R','C','L'].includes(p.type)){const y=p.type==='R'?cx(1/v):p.type==='C'?cx(0,w*v):cx(0,-1/(w*v));stamp(p.a,p.b,y);terms.push({label:p.id,description:`${p.id} 复导纳 ${cfmt(y)} S 写入节点矩阵。`,lines:[p.type==='R'?`Y = 1/R = ${fmt(1/v)} S`:p.type==='C'?`Y = jωC = j${fmt(w*v)} S`:`Y = 1/(jωL) = −j${fmt(1/(w*v))} S`]})}else if(p.type==='I'){if(g.has(p.a))z[g.get(p.a)]=csub(z[g.get(p.a)],cx(v));if(g.has(p.b))z[g.get(p.b)]=cadd(z[g.get(p.b)],cx(v))}});
  vs.forEach((p,k)=>{const r=nodes.length+k,i=g.get(p.a),j=g.get(p.b);if(i!==undefined){A[i][r]=cadd(A[i][r],cx(1));A[r][i]=cadd(A[r][i],cx(1))}if(j!==undefined){A[j][r]=csub(A[j][r],cx(1));A[r][j]=csub(A[r][j],cx(1))}z[r]=cx(parseValue(p.value));terms.push({label:p.id,description:`理想电压源加入支路电流未知量和电压约束。`,lines:[`${p.a} − ${p.b} = ${fmt(parseValue(p.value))}∠0° V`]})});
  try{const sol=solveComplex(A,z),unknowns=[...nodes.map(n=>`V(${n})`),...vs.map(p=>`I(${p.id})`)];state.last={type:'ac',A,z,x:sol.x,nodes,vs,unknowns,terms,pivots:sol.pivots,parts:ps,frequency:f};$('#equationBox').textContent=`交流 MNA：A(jω)x = z\nf = ${fmt(f)} Hz，ω = 2πf = ${fmt(w)} rad/s\n`+A.map((r,i)=>`[ ${r.map(cfmt).join('  ')} ] [${unknowns[i]}] = ${cfmt(z[i])}`).join('\n')+`\n\n解向量：\n`+sol.x.map((q,i)=>`${unknowns[i]} = ${fmt(cabs(q))} ∠ ${fmt(cdeg(q))}°`).join('\n');renderACResult();renderACSteps();renderWaveform();$('#solveStatus').textContent='已收敛';$('#unknownCount').textContent=N;$('#resultCaption').textContent='峰值相量：幅值 / 相位';toast('交流相量分析完成')}catch(e){toast(e.message);$('#solveStatus').textContent='求解失败';$('#unknownCount').textContent='—';$('#equationBox').textContent=`交流求解失败：${e.message}`}
}
function renderACResult(){const {x,nodes,vs,parts,frequency}=state.last,polar=(z,unit)=>`${fmt(cabs(z))} ∠ ${fmt(cdeg(z))}° ${unit}`,voltage=n=>n==='0'?cx():nodes.includes(n)?x[nodes.indexOf(n)]:null;const rows=nodes.map((n,i)=>[`V(${n})`,polar(x[i],'V')]);vs.forEach((p,k)=>rows.push([`I(${p.id})`,polar(x[nodes.length+k],'A')]));const branchRows=parts.map(p=>{const va=voltage(p.a),vb=voltage(p.b),v=va&&vb?csub(va,vb):null;let i=null,relation='';if(p.type==='I'){i=cx(parseValue(p.value));relation='独立电流源，方向 a → b'}else if(p.type==='V'){const k=vs.findIndex(q=>q.id===p.id);i=k<0?null:x[nodes.length+k];relation='理想电压源支路电流，正方向 a → b'}else if(v){if(p.type==='R'){i=cmul(v,cx(1/parseValue(p.value)));relation=`I=V/R，R=${fmt(parseValue(p.value))} Ω`}else if(p.type==='C'){i=cmul(v,cx(0,2*Math.PI*frequency*parseValue(p.value)));relation=`I=jωCV，f=${fmt(frequency)} Hz`}else if(p.type==='L'){i=cmul(v,cx(0,-1/(2*Math.PI*frequency*parseValue(p.value))));relation=`I=V/(jωL)，f=${fmt(frequency)} Hz`}}return `<tr><td>${p.id}（${labels[p.type]}）</td><td>${v?polar(v,'V'):'—'}</td><td>${i?polar(i,'A'):'—'}</td><td>${relation}</td></tr>`});$('#resultBox').innerHTML=`<table class="result-table"><thead><tr><th>相量</th><th style="text-align:right">峰值 ∠ 相位</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td></tr>`).join('')}</tbody></table><h3 class="analysis-subtitle">元件支路相量（a → b）</h3><div class="table-wrap"><table class="result-table"><thead><tr><th>元件</th><th>电压 Vab</th><th>电流 Iab</th><th>计算关系</th></tr></thead><tbody>${branchRows.join('')}</tbody></table></div><p class="note">表中为峰值相量；正相位方向按复数相量约定。电流参考方向为 a → b。</p>`}
function renderACSteps(){const {terms,pivots,x,unknowns,frequency}=state.last,items=[{label:'频率与未知量',description:`f = ${fmt(frequency)} Hz，ω = 2πf。电压、电流源视为 0° 峰值相量。`,lines:[`x = [${unknowns.join(', ')}]ᵀ`,`电容 Y=jωC；电感 Y=1/(jωL)`]},...terms,{label:'组装复数 MNA 方程',description:'将各元件复导纳及独立源贡献相加，形成 A(jω)x=z。',lines:[`矩阵维数 ${state.last.A.length} × ${state.last.A.length}`]},{label:'复数高斯消元',description:'采用部分主元复数高斯消元求解。',lines:[`消元步数 ${pivots.length}`,`解 = [${x.map(cfmt).join(', ')}]ᵀ`]}];$('#stepsBox').innerHTML=items.map((s,i)=>`<div class="step"><div class="step-n">${i+1}</div><div><h3>${s.label}</h3><p>${s.description}<br>${s.lines.map(l=>`<code>${l}</code>`).join('<br>')}</p></div></div>`).join('')}
function renderWaveform(){const {nodes,x,frequency,type}=state.last;if(!nodes.length){$('#wavePlot').innerHTML='<div class="empty">没有非参考节点可绘制</div>';return}const W=760,H=190,left=54,top=14,innerW=680,innerH=135,pts=[];let A,phase;if(type==='ac'){A=cabs(x[0]);phase=Math.atan2(x[0].im,x[0].re);for(let i=0;i<=120;i++){const t=i/120*2*Math.PI,y=A*Math.cos(t+phase),px=left+i/120*innerW,py=top+innerH/2-y/(A||1)*innerH*.42;pts.push(`${px.toFixed(1)},${py.toFixed(1)}`)}$('#plotCaption').textContent=`V(${nodes[0]}) · ${fmt(frequency)} Hz · 2 周期`}else{A=Math.abs(x[0]);const py=top+innerH/2-x[0]/(A||1)*innerH*.42;pts.push(`${left},${py}`,`${left+innerW},${py}`);$('#plotCaption').textContent=`V(${nodes[0]}) · 直流稳态`}$('#wavePlot').className='';$('#wavePlot').innerHTML=`<svg class="wave-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="节点电压波形"><line x1="${left}" y1="${top+innerH/2}" x2="${left+innerW}" y2="${top+innerH/2}" class="wave-axis"/><line x1="${left}" y1="${top}" x2="${left}" y2="${top+innerH}" class="wave-axis"/><line x1="${left}" y1="${top+innerH*.25}" x2="${left+innerW}" y2="${top+innerH*.25}" class="wave-grid"/><line x1="${left}" y1="${top+innerH*.75}" x2="${left+innerW}" y2="${top+innerH*.75}" class="wave-grid"/><polyline points="${pts.join(' ')}" class="wave-line"/><text x="8" y="22" class="wave-label">V (V)</text><text x="${left}" y="178" class="wave-label">0</text><text x="${left+innerW}" y="178" text-anchor="end" class="wave-label">${type==='ac'?'2T':'t'}</text><text x="${left+innerW/2}" y="188" text-anchor="middle" class="wave-label">时间</text><text x="${left+innerW-4}" y="18" text-anchor="end" class="wave-label">${type==='ac'?'峰值':'稳态'} ${fmt(A)} V</text></svg>`}
function runAnalysis(){
  if($('#analysisType').value==='ac'){runACAnalysis();return}
  let ps=state.parts.map(p=>({...p}));for(const p of ps){if(!validNode(p.a)||!validNode(p.b)){toast(`${p.id} 节点名无效`);return}if(p.a===p.b&&p.type!=='S'){toast(`${p.id} 两端不能连接到同一节点`);return}if(!['S'].includes(p.type)&&(!Number.isFinite(parseValue(p.value))||(p.type==='R'&&parseValue(p.value)<=0))){toast(`${p.id} 参数无法解析，请输入如 1k、10u 或 5`);return}}
  // DC equivalence: capacitor open, inductor and closed ideal switch short; open switch is open.
  ps=ps.filter(p=>p.type!=='C'&&!(p.type==='S'&&p.state==='open'));
  let parent={};for(const p of ps)for(const n of [p.a,p.b])parent[n]=n;for(const w of state.wires.filter(q=>q.a&&q.b))for(const n of [w.a,w.b])parent[n]=n;for(const j of state.junctions)parent[j.id]=j.id;const find=n=>{if(parent[n]!==n)parent[n]=find(parent[n]);return parent[n]};const union=(a,b)=>{a=find(a);b=find(b);if(a!==b){if(a==='0'||b==='0'){parent[a==='0'?b:a]='0'}else parent[b]=a}};state.wires.filter(w=>w.a&&w.b).forEach(w=>union(w.a,w.b));ps.filter(p=>p.type==='L'||p.type==='S').forEach(p=>union(p.a,p.b));
  const canon=n=>find(n);ps=ps.map(p=>({...p,a:canon(p.a),b:canon(p.b)}));const nodeSet=new Set(ps.flatMap(p=>[p.a,p.b]));nodeSet.delete('0');const roots=[...nodeSet].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));const netNames=new Map(roots.map((n,i)=>[n,state.custom?`N${i+1}`:n]));if(state.custom)ps=ps.map(p=>({...p,a:p.a==='0'?'0':netNames.get(p.a),b:p.b==='0'?'0':netNames.get(p.b)}));const nodes=state.custom?roots.map((_,i)=>`N${i+1}`):roots;const g=new Map(nodes.map((n,i)=>[n,i]));const vs=ps.filter(p=>p.type==='V'),N=nodes.length+vs.length;const A=Array.from({length:N},()=>Array(N).fill(0)),z=Array(N).fill(0),terms=[];if(!N){toast('请至少添加一个有源元件');return}
  ps.forEach(p=>{const a=p.a,b=p.b,v=parseValue(p.value);if(p.type==='R'){stamp(a,b,1/v,A,z,g,terms,p.id,`${p.id} 电阻 ${p.value}：两端并联导纳 1/R = ${fmt(1/v)} S。`)}else if(p.type==='I'){if(g.has(a))z[g.get(a)]-=v;if(g.has(b))z[g.get(b)]+=v;terms.push({label:p.id,description:`${p.id} 电流源 ${fmt(v)} A，方向 ${a} → ${b}；按 KCL 写入右端向量 z。`,lines:[`${a} 行：${a==='0'?'不写入':`z${g.get(a)+1} -= ${fmt(v)}`}`,`${b} 行：${b==='0'?'不写入':`z${g.get(b)+1} += ${fmt(v)}`}`]})}});
  vs.forEach((p,k)=>{const row=nodes.length+k,ia=g.get(p.a),ib=g.get(p.b),v=parseValue(p.value);if(ia!==undefined)A[ia][row]+=1;if(ib!==undefined)A[ib][row]-=1;if(ia!==undefined)A[row][ia]+=1;if(ib!==undefined)A[row][ib]-=1;z[row]=v;terms.push({label:p.id,description:`${p.id} 理想电压源：增加支路电流未知量 i${p.id}，并加入约束 V(${p.a}) − V(${p.b}) = ${fmt(v)} V。`,lines:[`MNA 第 ${row+1} 行/列：电压约束与支路电流耦合`,`z${row+1} = ${fmt(v)} V`]})});
  if(N>9){toast('当前演示求解限制为 9 个未知量以内');return}
  let solved;try{solved=solveLinear(A,z)}catch(e){toast(e.message);$('#solveStatus').textContent='求解失败';$('#unknownCount').textContent='—';$('#equationBox').textContent=`直流求解失败：${e.message}`;return}
  const unknowns=[...nodes.map(n=>`V(${n})`),...vs.map(p=>`I(${p.id})`)];state.last={type:'dc',A,z,x:solved.x,nodes,vs,unknowns,terms,pivots:solved.pivots,parts:ps};renderResult();renderEquation();renderSteps();renderWaveform();$('#resultCaption').textContent='单位：V / A';$('#solveStatus').textContent='已收敛';$('#unknownCount').textContent=N;toast('直流工作点已求解');
}
function renderEquation(){const {A,z,x,unknowns}=state.last,n=A.length;const rows=A.map((r,i)=>`[ ${r.map(fmt).map(s=>s.padStart(9)).join(' ')} ]  [${unknowns[i]}] = ${fmt(z[i])}`).join('\n');const vector=x.map((v,i)=>`${unknowns[i].padEnd(9)} = ${fmt(v)}`).join('\n');$('#equationBox').innerHTML=`<span class="accent">MNA 方程：</span> A x = z\n${rows}\n\n<span class="accent">解向量 x：</span>\n${vector}`}
function renderResult(){const {x,nodes,vs,parts}=state.last;let rows=nodes.map((n,i)=>[`V(${n})`,`<b>${fmt(x[i])}</b> V`]);vs.forEach((p,k)=>rows.push([`I(${p.id})`,`<b>${fmt(x[nodes.length+k])}</b> A`]));const voltage=n=>n==='0'?0:(nodes.includes(n)?x[nodes.indexOf(n)]:null),branchRows=parts.map(p=>{const va=voltage(p.a),vb=voltage(p.b),v=va===null||vb===null?null:va-vb;let current=null,relation='';if(p.type==='R'){current=v===null?null:v/parseValue(p.value);relation=`I=V/R，R=${fmt(parseValue(p.value))} Ω`}else if(p.type==='I'){current=parseValue(p.value);relation='独立电流源，方向 a → b'}else if(p.type==='V'){const k=vs.findIndex(q=>q.id===p.id);current=k<0?null:x[nodes.length+k];relation='理想电压源支路电流，正方向 a → b'}else if(p.type==='L'||p.type==='S'){relation='直流等效为理想短路；支路电流未单独求解'}const power=v===null||current===null?null:v*current;return `<tr><td>${p.id}（${labels[p.type]}）</td><td>${v===null?'—':`${fmt(v)} V`}</td><td>${current===null?'—':`${fmt(current)} A`}</td><td>${power===null?'—':`${fmt(power)} W`}</td><td>${relation}</td></tr>`});$('#resultBox').innerHTML=`<table class="result-table"><thead><tr><th>变量</th><th style="text-align:right">数值</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td></tr>`).join('')}</tbody></table><h3 class="analysis-subtitle">元件支路量（a → b）</h3><div class="table-wrap"><table class="result-table"><thead><tr><th>元件</th><th>电压 Vab</th><th>电流 Iab</th><th>吸收功率</th><th>计算关系</th></tr></thead><tbody>${branchRows.join('')}</tbody></table></div><p class="note">电压、电流按 a → b 参考方向；正功率表示元件吸收功率，负功率表示元件向电路供能。理想短路支路电流未由当前求解器单独计算。</p>`}
function renderSteps(){const {terms,pivots,x,unknowns}=state.last;const items=[{label:'节点编号与未知量',description:`参考节点为 0。其余节点为 ${unknowns.slice(0,state.last.nodes.length).join('、')||'无'}；理想电压源引入额外支路电流未知量。`,lines:[`x = [${unknowns.join(', ')}]ᵀ`,`按直流等效：C 开路，L 短路，闭合开关短路。`]},...terms,{label:'组装线性方程',description:'将各元件对节点电导矩阵、源向量及电压约束的贡献相加，得到 Ax = z。',lines:[`矩阵维数：${state.last.A.length} × ${state.last.A.length}`,`已按列主元消元并回代。`]}, {label:'消元与数值解',description:'采用部分主元高斯消元，降低小主元带来的数值误差。',lines:[`消元步数：${pivots.length}`,`x = [${x.map(fmt).join(', ')}]ᵀ`]}];$('#stepsBox').innerHTML=items.map((s,i)=>`<div class="step"><div class="step-n">${i+1}</div><div><h3>${s.label}</h3><p>${s.description}<br>${s.lines.map(l=>`<code>${l}</code>`).join('<br>')}</p></div></div>`).join('')}
function addPart(){const type=$('#newType').value,id=nextPartId(type),value=type==='S'?'open':$('#newValue').value.trim()||'1k';if(state.custom)state.parts.push({id,type,a:`${id}.a`,b:`${id}.b`,value,state:'open',x:350,y:130});else state.parts.push({id,type,a:'n1',b:'0',value,state:'open'});invalidateResults();renderParts();renderCircuit()}
function reset(){state.parts=[{id:'V1',type:'V',a:'n1',b:'0',value:'12',state:'closed'},{id:'R1',type:'R',a:'n1',b:'n2',value:'1k',state:'closed'},{id:'R2',type:'R',a:'n2',b:'0',value:'2k',state:'closed'},{id:'R3',type:'R',a:'n2',b:'0',value:'3k',state:'closed'},{id:'S1',type:'S',a:'n1',b:'n2',value:'open',state:'open'}];state.nodePos={n1:{x:160,y:82},n2:{x:495,y:82},'0':{x:325,y:218}};state.wires=[];state.wireDraft=null;state.junctions=[];state.custom=false;state.drawMode='connect';state.pendingNodes=[];state.last=null;$('#analysisType').value='dc';renderParts();renderCircuit();$('#solveStatus').textContent='等待运行';$('#unknownCount').textContent='—';$('#equationBox').textContent='点击「运行分析」生成矩阵方程 Ax = z。';$('#resultBox').innerHTML='<div class="empty">运行分析后显示节点电压与支路电流</div>';$('#stepsBox').innerHTML='<div class="empty">完成一次分析后，这里会逐步解释每个元件如何写入矩阵。</div>'}
$('#addBtn').addEventListener('click',addPart);$('#solveBtn').addEventListener('click',runAnalysis);$('#resetBtn').addEventListener('click',reset);$('#showDc').addEventListener('click',()=>$('#equationBox').scrollIntoView({behavior:'smooth',block:'center'}));$('#showExamples').addEventListener('click',()=>toast('点击右上方“恢复示例”载入预设分压电路。'));$('#showAbout').addEventListener('click',()=>toast('输入节点名并设置元件值，点击运行分析查看 MNA 组装过程。'));
$('#placeMode').addEventListener('click',()=>setCustomMode('place'));$('#wireMode').addEventListener('click',()=>setCustomMode('wire'));$('#junctionMode').addEventListener('click',()=>setCustomMode('junction'));$('#groundMode').addEventListener('click',()=>setCustomMode('ground'));$('#moveMode').addEventListener('click',()=>setCustomMode('move'));$('#rotateMode').addEventListener('click',()=>setCustomMode('rotate'));$('#deleteMode').addEventListener('click',setDeleteMode);$('#undoWire').addEventListener('click',undoWire);$('#newCircuit').addEventListener('click',startNewCircuit);
$('#expandCanvas').addEventListener('click',openCanvas);$('#closeCanvas').addEventListener('click',closeCanvas);
$('#drawType').addEventListener('change',()=>{state.lastPlacedPartId=null;updateParameterPrompt()});$('#drawValue').addEventListener('change',updateLastPlacedValue);$('#drawUnit').addEventListener('change',updateLastPlacedValue);$('#drawState').addEventListener('change',updateLastPlacedValue);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#canvasOverlay').hidden){closeCanvas();return}if(e.key==='Escape'&&(state.pendingNodes.length||state.wirePointer||state.wireDraft)){state.pendingNodes=[];state.wirePointer=null;state.wireDraft=null;if(state.custom)renderCustomCircuit();else renderCircuit()}});
document.querySelectorAll('.analysis-tabs button').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.analysis-tabs button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');state.method=btn.dataset.method;$('#analysisHint').textContent=state.method==='mna'?'当前求解器使用改进节点法。直流时电容开路、电感视为短路；开关按当前状态处理。':`${btn.textContent}用于展示方法对比入口；当前计算内核统一采用 MNA。`}));
$('#analysisType').addEventListener('change',e=>{$('#acControls').hidden=e.target.value!=='ac';$('#analysisHint').textContent=e.target.value==='dc'?'直流时电容开路、电感视为短路；开关按当前状态处理。':`交流分析使用复数 MNA，按峰值相量计算；电容和电感按频率换算复导纳。`;if(state.last)invalidateResults()});
updateParameterPrompt();renderParts();renderCircuit();
